-- Down Migration 0159: clear the explanation texts written by 0159
--
-- Sets short_description, what_it_measures and why_it_matters back to NULL for a metric only while all three still
-- equal the text 0159 wrote, so text that existed before 0159 or an admin edit made since is kept.
-- Forgets the manual_migrations row so db:migrate:manual re-applies 0159.

UPDATE site_metrics AS m
SET short_description = NULL, what_it_measures = NULL, why_it_matters = NULL, updated_at = now()
FROM (VALUES
-- Physical measurements (tracking)
('WEIGHT_LBS', 'Your body weight in pounds.',
 'Body weight is measured on a scale in pounds. It is recorded as a number to follow over time, not as a score.',
 'Weight helps put other results in context, such as speed, power and jump numbers. Watching it over time shows growth and training changes.'),
('HEIGHT_IN', 'How tall you are, in inches.',
 'Standing height, measured without shoes in inches. It is recorded to follow growth, not as a score.',
 'Height changes quickly during growth years. Knowing it helps coaches read your other results fairly and spot growth spurts.'),
('STANDING_REACH', 'How high you can reach with one arm straight up, flat-footed.',
 'Standing reach is the height of your fingertips with one arm stretched straight overhead and both feet flat on the floor.',
 'It is the starting point for reach-based jump measurements. Subtracting it from your approach or block touch height gives your actual jump.'),
('WINGSPAN', 'The distance from fingertip to fingertip with your arms stretched wide.',
 'Wingspan is measured across your back with both arms held straight out to the sides, from the tip of one middle finger to the other.',
 'Arm length affects reach, blocking and defending. It is a body measurement that you track, not a score to improve.'),
-- Reach and jump (volleyball style)
('APPROACH_REACH', 'The highest point you can touch with a running approach jump.',
 'Approach reach is the height you touch at the top of a jump taken after a running approach, as you would to attack a ball.',
 'It shows how high you can actually attack. Taken with your standing reach it gives your approach jump.'),
('APPROACH_JUMP', 'How much height you gain from a running approach jump.',
 'Approach jump is your approach reach minus your standing reach, so it is the number of inches you add by jumping off a run-up.',
 'This is the jump that matters for attacking. A bigger approach jump means a higher hitting point.'),
('BLOCK_REACH', 'The highest point you can touch with a two-foot block jump.',
 'Block reach is the height you touch at the top of a two-foot jump with both arms reaching over the net position, taken from a standing start.',
 'It shows how high you can get your hands when blocking. Taken with your standing reach it gives your block jump.'),
('BLOCK_JUMP', 'How much height you gain from a standing block jump.',
 'Block jump is your block reach minus your standing reach, so it is the number of inches you add by jumping from a standing start.',
 'It shows how well you can get up to block without a run-up. A bigger block jump means a higher block.'),
-- Dashes (yards)
('DASH_5YD', 'How fast you cover your first 5 yards from a standing start.',
 'The time it takes to sprint 5 yards from a standing start, in seconds.',
 'Games are often decided in the first few steps. This shows how explosively you get moving.'),
('DASH_10YD', 'How fast you cover 10 yards from a standing start.',
 'The time it takes to sprint 10 yards from a standing start, in seconds.',
 'The first 10 yards show how quickly you accelerate. It is also the straight-line sprint time used to work out your change-of-direction cost.'),
('DASH_20YD', 'How fast you cover 20 yards from a standing start.',
 'The time it takes to sprint 20 yards from a standing start, in seconds.',
 'Twenty yards is a common distance in field and court sports. It shows how well you keep building speed after the first steps.'),
('DASH_30YD', 'How fast you cover 30 yards from a standing start.',
 'The time it takes to sprint 30 yards from a standing start, in seconds.',
 'It shows acceleration carried over a longer distance, where you start to approach your top speed.'),
-- Dashes (meters) and fly
('DASH_10M', 'How fast you cover the first 10 meters of a sprint.',
 'The time at the 10-meter timing gate during a sprint from a standing start, in seconds.',
 'The first 10 meters show how explosively you accelerate, which is what most games and matches reward.'),
('DASH_20M', 'How fast you cover the first 20 meters of a sprint.',
 'The time at the 20-meter timing gate during a sprint from a standing start, in seconds.',
 'It shows how well you keep accelerating after the first few steps.'),
('DASH_30M', 'How fast you cover the first 30 meters of a sprint.',
 'The time at the 30-meter timing gate during a sprint from a standing start, in seconds.',
 'By 30 meters most athletes are close to top speed, so this shows acceleration turning into speed.'),
('DASH_40M', 'How fast you cover the first 40 meters of a sprint.',
 'The time at the 40-meter timing gate during a sprint from a standing start, in seconds.',
 'Over 40 meters you reach and hold close to your top speed. Coaches also use it to build a full picture of your force and speed profile.'),
('FLY10M_TIME', 'How fast you cover 10 meters once you are already at full speed.',
 'The time it takes to run 10 meters after a flying start, in seconds. It is the metric version of the 10-yard fly and is essentially a top-speed measurement.',
 'Top speed separates fast athletes from the fastest. In games you are often already moving, and this shows how fast you really are without acceleration.'),
-- Reactive strength (single leg and asymmetry)
('RSI_L', 'How quickly and how high you bounce on your left leg alone.',
 'In the 10/5 repeat hop test you do 10 hops on one leg, then your best 5 are averaged. Reactive Strength Index is how long you stay in the air divided by how long you touch the ground, shown here for the left leg.',
 'Springy, quick hops come from using the tendon spring in your leg well. Comparing the left leg with the right shows imbalances.'),
('RSI_R', 'How quickly and how high you bounce on your right leg alone.',
 'In the 10/5 repeat hop test you do 10 hops on one leg, then your best 5 are averaged. Reactive Strength Index is how long you stay in the air divided by how long you touch the ground, shown here for the right leg.',
 'Springy, quick hops come from using the tendon spring in your leg well. Comparing the right leg with the left shows imbalances.'),
('RSI_SINGLE_LEFT', 'How quickly and how high you bounce on your left leg alone.',
 'Reactive Strength Index for the left leg only: how long you stay in the air divided by how long you touch the ground during single-leg hops.',
 'It shows how springy and reactive the left leg is on its own. Comparing it with the right leg shows imbalances.'),
('RSI_SINGLE_RIGHT', 'How quickly and how high you bounce on your right leg alone.',
 'Reactive Strength Index for the right leg only: how long you stay in the air divided by how long you touch the ground during single-leg hops.',
 'It shows how springy and reactive the right leg is on its own. Comparing it with the left leg shows imbalances.'),
('RSI_ASYM', 'How different your left and right legs are on the hop test, in percent.',
 'The percentage gap between your left-leg and right-leg Reactive Strength Index. 0% means both legs are the same; larger numbers mean one leg is stronger.',
 'A big gap between legs is linked to a higher risk of injury and can slow your return from one. Lower is better; a small gap is normal.'),
-- Agility (5-10-5 and 5-0-5)
('AGILITY_5105_L', 'Your 5-10-5 shuttle time when you start by going left.',
 'You start in the middle, sprint 5 yards left, turn and sprint 10 yards right, then turn and finish through the middle. Time is in seconds, and this version starts to the left.',
 'It tests how well you accelerate, brake, turn and re-accelerate. Comparing left and right starts shows whether one direction is weaker.'),
('AGILITY_5105_R', 'Your 5-10-5 shuttle time when you start by going right.',
 'You start in the middle, sprint 5 yards right, turn and sprint 10 yards left, then turn and finish through the middle. Time is in seconds, and this version starts to the right.',
 'It tests how well you accelerate, brake, turn and re-accelerate. Comparing left and right starts shows whether one direction is weaker.'),
('AGILITY_505_M_L', 'Your 5-0-5 turn time pushing off the left foot (meters).',
 'You build up speed over 10 meters, run 5 more to the turn line, turn 180 degrees and sprint 5 back. The clock covers those last 5 meters in and 5 out, and you turn off your left foot.',
 'It isolates how well you slow down and change direction on one side. Comparing left with right shows whether you favor a side.'),
('AGILITY_505_M_R', 'Your 5-0-5 turn time pushing off the right foot (meters).',
 'You build up speed over 10 meters, run 5 more to the turn line, turn 180 degrees and sprint 5 back. The clock covers those last 5 meters in and 5 out, and you turn off your right foot.',
 'It isolates how well you slow down and change direction on one side. Comparing right with left shows whether you favor a side.'),
('AGILITY_505_M_LSI', 'How evenly your left and right turns match in the 5-0-5, in percent.',
 'Limb Symmetry Index compares your faster turn with your slower one: faster time divided by slower time, times 100. 100% means both sides are equal.',
 'A score under about 90% means one side is clearly weaker, which is linked to a higher injury risk. Higher is better, up to 100%.'),
('AGILITY_505_YD_L', 'Your 5-0-5 turn time pushing off the left foot (yards).',
 'You build up speed over 10 yards, run 5 more to the turn line, turn 180 degrees and sprint 5 back. The clock covers those last 5 yards in and 5 out, and you turn off your left foot.',
 'It isolates how well you slow down and change direction on one side. Comparing left with right shows whether you favor a side.'),
('AGILITY_505_YD_R', 'Your 5-0-5 turn time pushing off the right foot (yards).',
 'You build up speed over 10 yards, run 5 more to the turn line, turn 180 degrees and sprint 5 back. The clock covers those last 5 yards in and 5 out, and you turn off your right foot.',
 'It isolates how well you slow down and change direction on one side. Comparing right with left shows whether you favor a side.'),
('AGILITY_505_YD_LSI', 'How evenly your left and right turns match in the 5-0-5, in percent.',
 'Limb Symmetry Index compares your faster turn with your slower one: faster time divided by slower time, times 100. 100% means both sides are equal.',
 'A score under about 90% means one side is clearly weaker, which is linked to a higher injury risk. Higher is better, up to 100%.'),
-- Jumps and power
('JUMP_SJ_HEIGHT', 'How high you jump from a held squat with no dip and no arm swing.',
 'You hold a squat at about 90 degrees for a few seconds, hands on hips, then jump without dipping first. This removes the stored spring energy, so it shows pure leg push.',
 'Compared with your counter-movement jump it shows whether you gain from the spring in your legs or need more strength.'),
('JUMP_BROAD', 'How far you can jump forward from a standing start.',
 'You stand behind a line, swing down and jump forward as far as possible with a two-foot take-off. Distance is from the line to the nearest heel on landing.',
 'It shows forward explosive power, which matters for sprinting and acceleration. Together with the vertical jumps it gives a full power picture.'),
('JUMP_CMJ_HOH', 'How high you jump with a quick dip, hands on hips.',
 'A counter-movement jump with your hands held on your hips: you dip to about 90 degrees and jump straight up with no arm swing. Height is in inches.',
 'It shows leg power without help from the arms. It is also used with your squat jump to work out how well you use your leg spring.'),
('JUMP_CMJ_SL_L', 'How high you jump on your left leg alone, hands on hips.',
 'A single-leg counter-movement jump: you take off and land on the left leg only, dip, and jump straight up with your hands on your hips.',
 'It shows how powerful each leg is on its own. Comparing it with the right leg can show imbalances.'),
('JUMP_CMJ_SL_R', 'How high you jump on your right leg alone, hands on hips.',
 'A single-leg counter-movement jump: you take off and land on the right leg only, dip, and jump straight up with your hands on your hips.',
 'It shows how powerful each leg is on its own. Comparing it with the left leg can show imbalances.'),
('POWER_EUR', 'How much your leg spring adds to your jump.',
 'Eccentric Utilization Ratio is your counter-movement jump height divided by your squat jump height. A higher number means you gain more from the quick dip before jumping.',
 'A low number suggests training that builds bounce and spring; a high number suggests building raw leg strength. It points your training in the right direction.'),
('MOMENTUM', 'How much momentum you carry when running, from your weight and speed.',
 'Momentum is your body mass multiplied by your 10-yard fly speed. A heavier athlete scores higher at the same speed.',
 'It matters in contact and collision sports. It is tracked, not ranked, because bigger athletes naturally score higher.'),
('PEAK_POWER_W', 'An estimate of the peak power in your jump, in watts.',
 'Estimated from your hands-on-hips counter-movement jump height and your body weight with the Sayers equation. It uses the weight closest to the jump date, within 45 days.',
 'Peak power is a top predictor of sprint and jump performance. It is an estimate, and a heavier athlete scores higher at the same jump, so it is tracked, not ranked. The equation was built on adults, so youth values are approximate.'),
('PEAK_POWER_REL', 'An estimate of your jump power for each kilogram of body weight.',
 'The Sayers peak power estimate divided by your body mass, in watts per kilogram. It uses your hands-on-hips counter-movement jump and the weight closest to the jump date, within 45 days.',
 'It compares athletes of different sizes fairly, because it shows power for each unit of body weight. It is an estimate based on an adult equation, so youth values are approximate.'),
-- Conditioning
('COND_YYIR1_DISTANCE', 'How far you run in the Yo-Yo test before you cannot keep pace.',
 'The Yo-Yo Intermittent Recovery Test Level 1: you run 20-meter shuttles at increasing speed, with short rests, until you miss the pace twice. Your score is the total distance in meters.',
 'It shows the stamina you need to keep making repeated hard efforts in a game, such as in soccer. A longer distance means better fitness.'),
('COND_VO2MAX_EST', 'An estimate of your aerobic fitness from your Yo-Yo test distance.',
 'VO2max is the most oxygen your body can use per kilogram per minute. This value is estimated from your Yo-Yo test distance (distance x 0.0084 + 36.4).',
 'It puts your fitness in a standard number that families and coaches can compare. It is an estimate, not a lab test.'),
-- Movement quality (patterns, scored 0-3 by a coach from video)
('MQ_LIN_ACCEL', 'How well you move when you sprint away from a standing start.',
 'A coach scores your linear acceleration from video: 3 Efficient, 2 Functional, 1 Compensated, 0 Absent.',
 'Good acceleration technique lets you turn strength into speed with less wasted effort and lower injury risk.'),
('MQ_MAX_VELO', 'How well you move when you run at top speed.',
 'A coach scores your max-velocity running form from video: 3 Efficient, 2 Functional, 1 Compensated, 0 Absent.',
 'Clean top-speed mechanics help you run faster with less strain on your body.'),
('MQ_DECEL', 'How well you slow down and stop.',
 'A coach scores your deceleration from video: 3 Efficient, 2 Functional, 1 Compensated, 0 Absent.',
 'Being able to brake under control is what lets you cut and change direction safely, and it protects knees and ankles.'),
('MQ_SHUFFLE', 'How well you move sideways in a shuffle.',
 'A coach scores your lateral shuffle from video: 3 Efficient, 2 Functional, 1 Compensated, 0 Absent.',
 'Many sports need quick, balanced side-to-side movement, such as defending and covering the court.'),
('MQ_LATRUN', 'How well you run sideways with a crossover step.',
 'A coach scores your lateral crossover run from video: 3 Efficient, 2 Functional, 1 Compensated, 0 Absent.',
 'It shows how smoothly you cover ground sideways at speed, which matters in defense and in tracking opponents.'),
('MQ_HIPTURN', 'How well you turn your hips to change direction.',
 'A coach scores your hip turn from video: 3 Efficient, 2 Functional, 1 Compensated, 0 Absent.',
 'A smooth hip turn lets you change direction without losing speed, such as when you turn to chase a ball.'),
('MQ_BACKPEDAL', 'How well you run backward.',
 'A coach scores your backpedal from video: 3 Efficient, 2 Functional, 1 Compensated, 0 Absent.',
 'Controlled backward movement lets you keep your eyes on play while you retreat and defend.'),
('MQ_JUMP', 'How well you take off and land when you jump.',
 'A coach scores your jumping and landing technique from video: 3 Efficient, 2 Functional, 1 Compensated, 0 Absent.',
 'Good landing and take-off mechanics help you jump higher and protect your knees and ankles.'),
('MQI_TOTAL', 'Your overall movement quality score, out of 24.',
 'The Movement Quality Index is the total of your eight movement pattern scores, each 0 to 3, so the top score is 24. It only appears when all eight are scored on the same date.',
 'It gives one number for how well you move overall and shows which patterns to work on. A higher score means cleaner movement.'),
-- Movement quality (transitions, optional)
('MQ_TRANS_DECEL_CUT', 'How well you go from slowing down into a sideways cut.',
 'A coach scores the transition from deceleration to a lateral cut from video: 3 Efficient, 2 Functional, 1 Compensated, 0 Absent.',
 'Real games link movements together. This shows whether you can brake and then change direction smoothly.'),
('MQ_TRANS_GAS_BRAKE', 'How well you switch between speeding up and slowing down.',
 'A coach scores your transitions between accelerating and braking from video: 3 Efficient, 2 Functional, 1 Compensated, 0 Absent.',
 'Starting and stopping again and again is what most sports ask of you. Smooth switches save energy and reduce injury risk.'),
('MQ_TRANS_BACKPEDAL_TURN', 'How well you go from running backward into a forward sprint.',
 'A coach scores the transition from backpedal to hip turn to sprint from video: 3 Efficient, 2 Functional, 1 Compensated, 0 Absent.',
 'This is the move when a ball goes over your head. A smooth switch keeps you in the play.'),
('MQ_TRANS_LAT_LINEAR', 'How well you go from moving sideways into a straight sprint.',
 'A coach scores the transition from lateral movement to linear running from video: 3 Efficient, 2 Functional, 1 Compensated, 0 Absent.',
 'Moving sideways then breaking into a sprint is common in defense and attack. A smooth switch keeps your speed.'),
('MQ_TRANSITION_TOTAL', 'Your overall transition score, out of 12.',
 'The total of your four transition scores, each 0 to 3, so the top score is 12. It only appears when all four are scored on the same date, and it is separate from the MQI total.',
 'It shows how well you link movements together, which is where many game situations are won or lost. A higher score means smoother transitions.')
) AS v(code, short_description, what_it_measures, why_it_matters)
WHERE m.code = v.code
  AND m.short_description = v.short_description
  AND m.what_it_measures = v.what_it_measures
  AND m.why_it_matters = v.why_it_matters;

DO $$
BEGIN
  IF to_regclass('manual_migrations') IS NOT NULL THEN
    DELETE FROM manual_migrations WHERE migration_name = '0159_backfill_metric_explanations';
  END IF;
END $$;
